#define CAPTURED_FRAMEBUFFER_BYTES APP_OLED_FRAMEBUFFER_BYTES

static uint8_t captured_framebuffer[CAPTURED_FRAMEBUFFER_BYTES];
static size_t captured_framebuffer_length;
static bool captured_framebuffer_overflow;

static oled_port_status_t oled_port_record_write(uint8_t address_7bit,
                                                  uint8_t control_byte,
                                                  const uint8_t *data,
                                                  size_t length,
                                                  int cmock_num_calls)
{
    (void)address_7bit;
    (void)cmock_num_calls;

    if ((control_byte == APP_OLED_DATA_CONTROL_BYTE) && (data != NULL))
    {
        if (length > (CAPTURED_FRAMEBUFFER_BYTES - captured_framebuffer_length))
        {
            captured_framebuffer_overflow = true;
        }
        else
        {
            memcpy(&captured_framebuffer[captured_framebuffer_length], data, length);
            captured_framebuffer_length += length;
        }
    }

    return (oled_port_status_t)0;
}

static sh1106_status_t expected_display_write(void *context,
                                               uint8_t address_7bit,
                                               uint8_t control_byte,
                                               const uint8_t *data,
                                               size_t length)
{
    (void)context;
    (void)address_7bit;
    (void)control_byte;
    (void)data;
    (void)length;
    return SH1106_STATUS_OK;
}

