void setUp(void)
{
    memset(captured_framebuffer, 0, sizeof(captured_framebuffer));
    captured_framebuffer_length = 0U;
    captured_framebuffer_overflow = false;
    oled_port_write_StubWithCallback(oled_port_record_write);
}

